/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["arbeit-finden"]={"Das eigene Suchprofil festlegen":"تعیین پروفایل جستجوی خودتان","Du leitest ein Suchprofil aus Fähigkeiten, Zeitfenstern und erreichbaren Arbeitsorten ab.":"شما از مهارت‌ها، بازه‌های زمانی و جاهای کاری قابل رسیدن یک پروفایل جستجو می‌سازید.","Wunsch und Grenze gleichsetzen":"یکی دانستن خواسته و محدودیت","Falsch: Jede Vorliebe als unveränderliche Grenze behandeln. Richtig: Feste Zeitgrenzen von verhandelbaren Wünschen trennen.":"اشتباه: هر علاقه‌مندی را یک محدودیت غیرقابل تغییر بدانید. درست: محدودیت‌های زمانی ثابت را از خواسته‌های قابل مذاکره جدا کنید.","Fähigkeit ohne Beispiel behaupten":"ادعای مهارت بدون مثال","Falsch: „Ich bin für alles geeignet.“ Richtig: „Ich habe Kunden beraten und Ware eingeräumt.“":"اشتباه: „Ich bin für alles geeignet.“ (من برای همه چیز مناسبم.) درست: „Ich habe Kunden beraten und Ware eingeräumt.“ (من به مشتریان مشوره داده‌ام و جنس را در قفسه چیده‌ام.)","Welche Angabe ist eine belegte berufliche Tätigkeit?":"کدام معلومات یک کار شغلی ثابت‌شده است؟","Ich habe Waren eingeräumt.":"من جنس را در قفسه چیده‌ام.","Ich möchte künftig Waren einräumen.":"می‌خواهم در آینده جنس را در قفسه بچینم.","Ich würde gern Kunden beraten.":"دوست دارم به مشتریان مشوره بدهم.","Das Einräumen beschreibt eine konkrete Erfahrung statt einer pauschalen Behauptung.":"چیدن جنس یک تجربهٔ مشخص را توصیف می‌کند، نه یک ادعای کلی.","Was muss Huda bei einer Schicht besonders prüfen?":"هدی در یک شیفت به‌خصوص چه چیزی را باید بررسی کند؟","Ob allein die Fahrtzeit unter dreißig Minuten liegt.":"فقط اینکه آیا زمان رفت‌وآمد زیر سی دقیقه است.","Ob die Arbeitszeit mit ihrer Grenze vereinbar ist.":"اینکه آیا وقت کار با محدودیت او جور می‌آید.","Ob der Betrieb grundsätzlich Teilzeit anbietet.":"اینکه آیا محل کار اصولاً کار نیمه‌وقت دارد.","Ihre Verfügbarkeit bis 15 Uhr ist eine konkrete Grenze für die Auswahl.":"آماده بودن او تا ساعت 15 یک محدودیت مشخص برای انتخاب است.","Was gehört zum realistischen Arbeitsweg?":"چه چیزی جزو راه واقع‌بینانهٔ کار است؟","Nur die reine Fahrzeit ohne Anschlusswege.":"فقط زمان خالص سفر بدون راه‌های وصل‌کننده.","Die Entfernung unabhängig vom Schichtbeginn.":"فاصله، مستقل از شروع شیفت.","Fahrt, Umstieg und Fußweg.":"سفر، تعویض وسیله و راه پیاده.","Alle Abschnitte beeinflussen, wann Huda tatsächlich ankommt.":"همهٔ بخش‌ها اثر دارند که هدی واقعاً چه وقت می‌رسد.","Trenne in deinem Profil feste Grenzen von verhandelbaren Wünschen.":"در پروفایل خود محدودیت‌های ثابت را از خواسته‌های قابل مذاکره جدا کنید.","Über passende Arbeit sprechen":"صحبت دربارهٔ کار مناسب","Beraterin: „Welche Arbeit suchen Sie?“ Huda: „Ich habe im Verkauf gearbeitet. Wegen der Betreuung kann ich bis 15 Uhr arbeiten.“ Beraterin: „Wie weit können Sie fahren?“ Huda: „Mit dem Bus etwa dreißig Minuten.“ Beraterin: „Dann prüfen wir Verkaufsstellen mit passenden Schichten.“ Huda nennt Erfahrung und Grenzen, bevor sie einzelne Angebote auswählt.":"مشاور: «چه کاری جستجو می‌کنید؟» هدی: «در فروش کار کرده‌ام. به خاطر نگهداری از کودک می‌توانم تا ساعت 15 کار کنم.» مشاور: «تا چه فاصله‌ای می‌توانید رفت‌وآمد کنید؟» هدی: «با بس حدود سی دقیقه.» مشاور: «پس فروشگاه‌هایی با شیفت‌های مناسب را بررسی می‌کنیم.» هدی پیش از انتخاب پیشنهادهای جداگانه، تجربه و محدودیت‌های خود را می‌گوید.","Fähigkeiten mit Beispielen belegen":"ثابت کردن مهارت‌ها با مثال","Eine Fähigkeit wird durch eine konkrete Tätigkeit verständlich: „Ich habe Waren eingeräumt und Kunden beraten.“ „Ich kann alles“ ist kaum prüfbar. Sammle drei Tätigkeiten aus Beruf, Ausbildung oder ehrenamtlicher Arbeit. Unterscheide zwischen selbstständig beherrschten Aufgaben und solchen, bei denen du Anleitung brauchst.":"یک مهارت با یک کار مشخص قابل فهم می‌شود: „Ich habe Waren eingeräumt und Kunden beraten.“ «من همه کار می‌توانم» به سختی قابل بررسی است. سه کار از شغل، آموزش یا کار داوطلبانه جمع کنید. کارهایی را که مستقل انجام می‌دهید از کارهایی که در آن‌ها به راهنمایی نیاز دارید جدا کنید.","Zeit und Arbeitsweg realistisch prüfen":"بررسی واقع‌بینانهٔ وقت و راه کار","Für dein Zeitfenster zählen Arbeitszeit und Heimweg. Rechne auch den Weg zur Haltestelle und mögliche Umstiege ein. Endet die Schicht um 15 Uhr, bist du erst später zu Hause. Prüfe deshalb zwei Zeiten: Wann endet die Arbeit? Wann musst du zu Hause sein? Teste den Weg zu einer passenden Uhrzeit.":"برای بازهٔ زمانی شما وقت کار و راه بازگشت به خانه هر دو مهم‌اند. راه تا ایستگاه و تعویض‌های احتمالی را هم حساب کنید. اگر شیفت ساعت 15 تمام شود، شما دیرتر به خانه می‌رسید. به همین دلیل دو زمان را بررسی کنید: کار چه وقت تمام می‌شود؟ چه وقت باید خانه باشید؟ راه را در یک ساعت مناسب آزمایش کنید.","Suchkriterien gewichten":"وزن دادن به معیارهای جستجو","Notiere als Muss-Kriterien die wirklich festen Grenzen, etwa ein spätestes Arbeitsende. Wünsche wie ein besonders kurzer Weg stehen gesondert. So erkennst du passende Angebote, ohne jedes kleine Abweichen sofort auszuschließen. Kläre offene Schichtzeiten beim Betrieb, statt sie aus einem Foto der Anzeige abzuleiten.":"محدودیت‌های واقعاً ثابت را به عنوان معیارهای اجباری یادداشت کنید، مثلاً دیرترین پایان کار. خواسته‌هایی مثل یک راه به‌خصوص کوتاه جدا نوشته می‌شوند. به این ترتیب پیشنهادهای مناسب را می‌شناسید، بدون اینکه هر تفاوت کوچک را فوراً رد کنید. وقت‌های نامشخص شیفت را از خود محل کار بپرسید، به جای اینکه از عکس یک اعلان نتیجه بگیرید.","Ein Suchprofil ergänzen":"کامل کردن یک پروفایل جستجو","Setze „Verkauf“ und „15“ ein.":"„Verkauf“ و „15“ را بگذارید.","Suche die Angaben in Hudas Antwort.":"این معلومات را در جواب هدی پیدا کنید.","Das Profil enthält ihre Erfahrung und die zeitliche Grenze.":"پروفایل تجربه و محدودیت زمانی او را در بر دارد.","Huda hat Erfahrung im ___.":"هدی در ___ تجربه دارد.","Sie kann bis ___ Uhr arbeiten.":"او می‌تواند تا ساعت ___ کار کند.","Profilangaben ordnen":"مرتب کردن معلومات پروفایل","Ordne die Beispiele zu.":"مثال‌ها را وصل کنید.","Frage nach Können, Verfügbarkeit und Erreichbarkeit.":"دربارهٔ توانایی، آماده بودن و قابل رسیدن بودن بپرسید.","Die Angaben beschreiben unterschiedliche Auswahlkriterien.":"این معلومات معیارهای مختلف انتخاب را توصیف می‌کنند.","Waren einräumen":"چیدن جنس در قفسه","bis 15 Uhr":"تا ساعت 15","Bus und Fußweg":"بس و راه پیاده","Die Verfügbarkeit hören":"شنیدن زمان آماده بودن","Bis wann kann Huda arbeiten? Schreibe nur die Zahl.":"هدی تا چه وقت می‌تواند کار کند؟ فقط عدد را بنویسید.","Gefragt ist das späteste Ende.":"دیرترین پایان خواسته شده است.","Hudas feste Grenze liegt bei 15 Uhr.":"محدودیت ثابت هدی ساعت 15 است.","Ein eigenes fiktives Suchprofil schreiben":"نوشتن یک پروفایل جستجوی خیالی خودتان","Schreibe vier Sätze mit Erfahrung, zwei Tätigkeiten, Verfügbarkeit und Arbeitsweg.":"چهار جمله با تجربه، دو کار، زمان آماده بودن و راه کار بنویسید.","Benutze erfundene Angaben und prüfe ihre gegenseitige Plausibilität.":"معلومات ساختگی به کار ببرید و بررسی کنید که با هم منطقی باشند.","Das Beispiel ergibt ein nachvollziehbares Profil für die Stellensuche.":"این مثال یک پروفایل قابل فهم برای جستجوی کار می‌سازد.","Nennst du eine Erfahrung und zwei konkrete Tätigkeiten?":"آیا یک تجربه و دو کار مشخص را نام می‌برید؟","Ist deine zeitliche Verfügbarkeit eindeutig?":"آیا زمان آماده بودن شما روشن است؟","Berücksichtigst du den ganzen Arbeitsweg?":"آیا تمام راه کار را در نظر می‌گیرید؟","Trennst du feste Grenzen von bloßen Wünschen?":"آیا محدودیت‌های ثابت را از خواسته‌های ساده جدا می‌کنید؟","Ein Suchprofil verbindet Tätigkeiten und praktische Rahmenbedingungen.":"یک پروفایل جستجو کارها و شرایط عملی را به هم وصل می‌کند.","Ein Wunsch kann verhandelbar sein, eine feste Betreuungszeit möglicherweise nicht.":"یک خواسته ممکن است قابل مذاکره باشد، اما یک وقت ثابت نگهداری از کودک شاید نه.","Beschäftigungsformen auseinanderhalten":"جدا کردن شکل‌های استخدام","Befristet heißt: Ein Vertrag endet nach der vereinbarten Zeit oder nach einem vereinbarten Zweck. Du prüfst Umfang und Dauer einer Stelle getrennt.":"Befristet (موقت) یعنی: یک قرارداد بعد از زمان یا هدف توافق‌شده تمام می‌شود. شما اندازهٔ کار و مدت یک وظیفه را جدا بررسی می‌کنید.","Teilzeit mit Befristung verwechseln":"اشتباه گرفتن نیمه‌وقت با موقت","Falsch: „Teilzeit endet immer nach sechs Monaten.“ Richtig: Umfang und Vertragsdauer werden getrennt geprüft.":"اشتباه: «کار نیمه‌وقت همیشه بعد از شش ماه تمام می‌شود.» درست: اندازهٔ کار و مدت قرارداد جدا بررسی می‌شوند.","Unbefristet als feste Tageszeit lesen":"دائمی را یک وقت ثابت روزانه دانستن","Falsch: „Unbefristet bedeutet täglich von acht bis zwölf.“ Richtig: Der Begriff benennt kein tägliches Zeitfenster.":"اشتباه: «Unbefristet یعنی هر روز از هشت تا دوازده.» درست: این کلمه هیچ بازهٔ زمانی روزانه را نام نمی‌برد.","Welcher Begriff beschreibt die Dauer?":"کدام کلمه مدت را توصیف می‌کند؟","Teilzeit.":"Teilzeit (نیمه‌وقت).","Frühschicht.":"Frühschicht (شیفت صبح).","Unbefristet.":"Unbefristet (دائمی).","„Unbefristet“ bezeichnet ein Arbeitsverhältnis ohne von vornherein festgelegtes Enddatum.":"„Unbefristet“ یک رابطهٔ کاری بدون تاریخ پایان از پیش تعیین‌شده را نشان می‌دهد.","Was bleibt bei „20 Stunden pro Woche“ offen?":"در „20 Stunden pro Woche“ (20 ساعت در هفته) چه چیزی نامعلوم می‌ماند؟","Die genaue Verteilung auf die Tage.":"تقسیم دقیق روی روزها.","Die vereinbarte Zahl der Wochenstunden.":"تعداد توافق‌شدهٔ ساعت‌های هفته.","Dass der Arbeitsumfang zwanzig Stunden beträgt.":"اینکه اندازهٔ کار بیست ساعت است.","Die Wochenstundenzahl legt allein noch keinen konkreten Dienstplan fest.":"تعداد ساعت‌های هفته به تنهایی هنوز یک برنامهٔ کاری مشخص را تعیین نمی‌کند.","Welche Kombination ist möglich?":"کدام ترکیب ممکن است؟","Teilzeit bedeutet eine Befristung auf wenige Monate.":"نیمه‌وقت یعنی موقت بودن برای چند ماه.","Teilzeit und unbefristet.":"نیمه‌وقت و دائمی.","Vollzeit legt gleichzeitig das Vertragsende fest.":"تمام‌وقت هم‌زمان پایان قرارداد را تعیین می‌کند.","Umfang und Dauer lassen sich unabhängig voneinander kombinieren.":"اندازه و مدت را می‌شود مستقل از هم ترکیب کرد.","Prüfe bei jeder Stelle getrennt Wochenstunden, Vertragsdauer und Einsatzzeiten.":"در هر کار ساعت‌های هفته، مدت قرارداد و وقت‌های کار را جدا بررسی کنید.","Zwei Angebote vergleichen":"مقایسهٔ دو پیشنهاد","Rami: „In Angebot A steht Teilzeit, unbefristet. Angebot B ist Vollzeit für sechs Monate.“ Freundin: „Dann ist A kürzer am Tag?“ Rami: „Nicht unbedingt. Teilzeit sagt noch nicht, wie die Stunden verteilt sind.“ Freundin: „Und unbefristet heißt ohne festes Enddatum?“ Rami: „Ja. Die genauen Bedingungen muss ich im Angebot prüfen.“":"رامی: «در پیشنهاد A نوشته نیمه‌وقت، دائمی. پیشنهاد B تمام‌وقت برای شش ماه است.» دوستش: «پس A در روز کوتاه‌تر است؟» رامی: «نه لزوماً. نیمه‌وقت هنوز نمی‌گوید ساعت‌ها چطور تقسیم شده‌اند.» دوستش: «و دائمی یعنی بدون تاریخ پایان ثابت؟» رامی: «بلی. شرایط دقیق را باید در پیشنهاد بررسی کنم.»","Zwei verschiedene Fragen stellen":"پرسیدن دو سوال مختلف","„Vollzeit oder Teilzeit?“ betrifft den Arbeitsumfang. „Befristet oder unbefristet?“ betrifft die Dauer. Eine Teilzeitstelle kann befristet oder unbefristet sein. Vollzeit ist ebenfalls kein Versprechen einer dauerhaften Beschäftigung. Lies nach, wie viele Stunden vereinbart sind. Das Wort „Teilzeit“ allein nennt noch keine feste Stundenzahl.":"«تمام‌وقت یا نیمه‌وقت؟» به اندازهٔ کار مربوط است. «موقت یا دائمی؟» به مدت مربوط است. یک کار نیمه‌وقت می‌تواند موقت یا دائمی باشد. تمام‌وقت هم وعدهٔ یک استخدام همیشگی نیست. بخوانید که چند ساعت توافق شده است. کلمهٔ „Teilzeit“ به تنهایی هنوز تعداد ساعت ثابتی را نام نمی‌برد.","Weitere Begriffe einordnen":"مرتب کردن کلمه‌های دیگر","Eine Schicht ist ein Abschnitt der Arbeitszeit, etwa der Frühdienst. Ein Praktikum soll Einblick oder Lernerfahrung bieten. Frage nach Aufgaben, Anleitung und Bezahlung. Eine kurze Stelle ist nicht allein wegen ihrer Dauer ein Praktikum. Lass dir erklären, welche Arbeit du übernehmen sollst und welche Bedingungen gelten.":"یک شیفت بخشی از وقت کار است، مثلاً شیفت صبح. یک کارآموزی (Praktikum) باید دید یا تجربهٔ یادگیری بدهد. دربارهٔ کارها، راهنمایی و دستمزد بپرسید. یک کار کوتاه فقط به خاطر مدتش کارآموزی نیست. بخواهید برای شما توضیح دهند که کدام کار را به عهده می‌گیرید و کدام شرایط اعمال می‌شود.","Vor einer Entscheidung nachfragen":"پرسیدن پیش از یک تصمیم","Frage beispielsweise „Auf welche Wochentage verteilen sich die Stunden?“. Eine Angabe wie „20 Stunden“ beantwortet diese Frage noch nicht. Vergleiche die Antworten mit deinem Suchprofil. Kläre, ob rechtliche Regeln oder dein Aufenthaltstitel die Arbeit erlauben. „Teilzeit“ beantwortet diese Frage nicht. Nutze dafür eine passende Beratungsstelle.":"مثلاً بپرسید „Auf welche Wochentage verteilen sich die Stunden?“ (ساعت‌ها روی کدام روزهای هفته تقسیم می‌شوند؟). معلوماتی مثل «20 ساعت» هنوز به این سوال جواب نمی‌دهد. جواب‌ها را با پروفایل جستجوی خود مقایسه کنید. روشن کنید که آیا قاعده‌های قانونی یا اجازهٔ اقامت شما این کار را اجازه می‌دهند. «نیمه‌وقت» به این سوال جواب نمی‌دهد. برای این کار از یک مرکز مشاورهٔ مناسب استفاده کنید.","Beschäftigungsmerkmale ergänzen":"کامل کردن ویژگی‌های استخدام","Setze „Dauer“ und „Umfang“ ein.":"„Dauer“ (مدت) و „Umfang“ (اندازه) را بگذارید.","Stelle die Fragen „Wie lange?“ und „Wie viel?“.":"سوال‌های «چقدر طول می‌کشد؟» و «چقدر؟» را بپرسید.","Die zwei Begriffe beantworten verschiedene Fragen.":"این دو کلمه به سوال‌های مختلف جواب می‌دهند.","Befristet beschreibt die ___.":"Befristet ___ را توصیف می‌کند.","Teilzeit betrifft den ___.":"Teilzeit به ___ مربوط است.","Merkmale zuordnen":"وصل کردن ویژگی‌ها","Verbinde die Angabe mit dem Prüffeld.":"معلومات را به خانهٔ بررسی وصل کنید.","Eine Dauer ist etwas anderes als ein Wochentag.":"یک مدت چیز دیگری از یک روز هفته است.","Die Felder helfen, Angebote vollständig zu vergleichen.":"این خانه‌ها کمک می‌کنند پیشنهادها را کامل مقایسه کنید.","sechs Monate":"شش ماه","20 Wochenstunden":"20 ساعت در هفته","Montag und Mittwoch":"دوشنبه و چهارشنبه","Die Befristung hören":"شنیدن موقت بودن","Für wie viele Monate ist Angebot B vorgesehen? Schreibe eine Ziffer.":"پیشنهاد B برای چند ماه پیش‌بینی شده است؟ یک رقم بنویسید.","Gefragt ist die Dauer von B.":"مدت پیشنهاد B خواسته شده است.","Angebot B nennt sechs Monate als vorgesehenen Zeitraum.":"پیشنهاد B شش ماه را به عنوان مدت پیش‌بینی‌شده نام می‌برد.","Zwei Angebote sachlich vergleichen":"مقایسهٔ واقع‌بینانهٔ دو پیشنهاد","Schreibe drei Sätze zu A und B und eine Rückfrage zur Stundenverteilung von A.":"سه جمله دربارهٔ A و B و یک سوال دربارهٔ تقسیم ساعت‌های A بنویسید.","Bleibe bei den genannten Angaben und kennzeichne Unbekanntes.":"به معلومات نام‌برده بسنده کنید و چیزهای نامعلوم را مشخص کنید.","Der Vergleich ergänzt keine Vertragsdetails, die im Beispiel fehlen.":"این مقایسه هیچ جزئیات قراردادی را که در مثال نیست اضافه نمی‌کند.","Unterscheidest du Umfang und Vertragsdauer?":"آیا اندازهٔ کار و مدت قرارداد را جدا می‌کنید؟","Sind die sechs Monate nur Angebot B zugeordnet?":"آیا شش ماه فقط به پیشنهاد B نسبت داده شده؟","Vermeidest du erfundene Tageszeiten für A?":"آیا از ساختن وقت‌های روزانهٔ ساختگی برای A پرهیز می‌کنید؟","Enthält dein Text eine konkrete Frage zur Verteilung?":"آیا متن شما یک سوال مشخص دربارهٔ تقسیم ساعت‌ها دارد؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei gesetze-im-internet.de.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در gesetze-im-internet.de بررسی کنید.","Beschäftigungsbedingungen nachweisen":"قانون ثبت شرایط کار (Nachweisgesetz)","Arbeitsumfang und Vertragsdauer sind zwei getrennte Merkmale.":"اندازهٔ کار و مدت قرارداد دو ویژگی جدا هستند.","Die Verteilung der Stunden muss ausdrücklich geklärt werden.":"تقسیم ساعت‌ها باید صریحاً روشن شود.","Stellenanzeigen systematisch lesen":"خواندن منظم اعلان‌های کار","Du findest Aufgabe, Anforderung, Arbeitsort und Bewerbungsweg in einer Anzeige.":"شما کار، شرط، محل کار و راه درخواست را در یک اعلان پیدا می‌کنید.","Erwünscht als zwingende Bedingung lesen":"«مطلوب» را شرط اجباری خواندن","Falsch: „Erfahrung erwünscht heißt, ohne sie ist jede Bewerbung ausgeschlossen.“ Richtig: Der Wortlaut nennt zunächst einen Wunsch; Unklarheiten werden nachgefragt.":"اشتباه: «Erfahrung erwünscht یعنی بدون تجربه هر درخواستی رد می‌شود.» درست: این جمله اول یک خواسته را نام می‌برد؛ نامشخصی‌ها پرسیده می‌شوند.","Bewerbungsweg ignorieren":"نادیده گرفتن راه درخواست","Falsch: Unterlagen ohne Prüfung an irgendeine Adresse schicken. Richtig: Den in der Anzeige genannten Portalweg und Empfänger prüfen.":"اشتباه: اسناد را بدون بررسی به هر آدرسی بفرستید. درست: راه پورتال و گیرندهٔ نام‌برده در اعلان را بررسی کنید.","Was ist in der Anzeige eine Aufgabe?":"در اعلان کدام یک کار است؟","Erfahrung erwünscht.":"Erfahrung erwünscht (تجربه مطلوب است).","Gäste bedienen.":"Gäste bedienen (خدمت به مهمانان).","Bewerbung über das Portal.":"Bewerbung über das Portal (درخواست از راه پورتال).","Gäste bedienen beschreibt die Tätigkeit; die anderen Angaben betreffen Wunsch und Bewerbungsweg.":"خدمت به مهمانان کار را توصیف می‌کند؛ معلومات دیگر به خواسته و راه درخواست مربوط‌اند.","Wie soll die Bewerbung eingereicht werden?":"درخواست باید چطور فرستاده شود؟","Über das genannte Portal.":"از راه پورتال نام‌برده.","Per E-Mail an die allgemeine Caféadresse.":"با ایمیل به آدرس عمومی کافه.","Persönlich während einer Samstagsschicht.":"حضوری در یک شیفت شنبه.","Der Bewerbungsweg wird in der Anzeige ausdrücklich als Portal bezeichnet.":"راه درخواست در اعلان صریحاً پورتال نامیده شده است.","Was muss Jana wegen ihrer Zeitplanung prüfen?":"یانا به خاطر برنامهٔ زمانی خود چه چیزی را باید بررسی کند؟","Ob Samstagsarbeit in der Anzeige erwähnt ist.":"اینکه آیا کار شنبه در اعلان ذکر شده است.","Ob es sich um eine Stelle mit 25 Wochenstunden handelt.":"اینکه آیا این کاری با 25 ساعت در هفته است.","Welche Samstage und Schichtzeiten vorgesehen sind.":"کدام شنبه‌ها و وقت‌های شیفت پیش‌بینی شده‌اند.","Samstagsarbeit ist genannt, ihre konkrete Verteilung jedoch noch nicht.":"کار شنبه نام برده شده، اما تقسیم مشخص آن هنوز نه.","Markiere in einer Anzeige jeweils eine Aufgabe, eine Voraussetzung und eine noch offene Frage.":"در یک اعلان یک کار، یک شرط و یک سوال هنوز باز را علامت بزنید.","Eine Anzeige gemeinsam prüfen":"بررسی مشترک یک اعلان","Anzeige: „Servicekraft im Café, 25 Wochenstunden, auch samstags. Aufgaben: Gäste bedienen und Kasse führen. Erfahrung erwünscht. Bewerbung über unser Portal.“ Jana: „Muss ich Erfahrung haben?“ Ali: „Hier steht erwünscht, nicht zwingend erforderlich.“ Jana: „Dann beschreibe ich meine Erfahrung im Vereinscafé und frage nach der Einarbeitung.“":"اعلان: „Servicekraft im Café, 25 Wochenstunden, auch samstags. Aufgaben: Gäste bedienen und Kasse führen. Erfahrung erwünscht. Bewerbung über unser Portal.“ (کارمند خدمات در کافه، 25 ساعت در هفته، شنبه‌ها هم. کارها: خدمت به مهمانان و کار با صندوق. تجربه مطلوب است. درخواست از راه پورتال ما.) یانا: «آیا باید تجربه داشته باشم؟» علی: «اینجا نوشته مطلوب، نه حتماً لازم.» یانا: «پس تجربه‌ام در کافهٔ انجمن را توضیح می‌دهم و دربارهٔ آموزش اولیه می‌پرسم.»","Muss und Wunsch sprachlich erkennen":"شناختن اجبار و خواسته از روی زبان","„Erforderlich“, „zwingend“ und „Voraussetzung“ kennzeichnen meist notwendige Bedingungen. „Erwünscht“ oder „von Vorteil“ nennen häufig bevorzugte Kenntnisse. Prüfe den gesamten Satz: Eine Fahrerlaubnis kann für eine konkrete Aufgabe unverzichtbar sein. Bei Unklarheit hilft eine Rückfrage an den Betrieb, keine automatische Umdeutung aller Anforderungen zu unverbindlichen Wünschen.":"„Erforderlich“، „zwingend“ و „Voraussetzung“ معمولاً شرط‌های لازم را نشان می‌دهند. „Erwünscht“ یا „von Vorteil“ اغلب دانش ترجیحی را نام می‌برند. تمام جمله را بررسی کنید: یک گواهی‌نامهٔ رانندگی ممکن است برای یک کار مشخص ضروری باشد. در صورت نامشخصی، پرسیدن از محل کار کمک می‌کند، نه اینکه همهٔ شرط‌ها را خودکار خواسته‌های غیرالزامی بدانید.","Aufgaben mit eigenen Erfahrungen abgleichen":"مقایسهٔ کارها با تجربه‌های خودتان","Vergleiche jede wichtige Aufgabe mit deiner Erfahrung. Für „Kasse führen“ kannst du eine echte Kassentätigkeit nennen. Sage dazu, wo und wie lange du das gemacht hast. Erfahrung als Gast in einem Café reicht dafür nicht. Notiere auch Aufgaben, die du erst lernen musst. So bereitest du eine ehrliche Bewerbung vor.":"هر کار مهم را با تجربهٔ خود مقایسه کنید. برای „Kasse führen“ (کار با صندوق) می‌توانید یک کار واقعی با صندوق نام ببرید. بگویید کجا و چه مدت این کار را کرده‌اید. تجربه به عنوان مهمان در یک کافه برای این کافی نیست. کارهایی را هم که باید تازه یاد بگیرید یادداشت کنید. به این ترتیب یک درخواست صادقانه آماده می‌کنید.","Bewerbungsweg und Lücken beachten":"توجه به راه درخواست و کمبودها","Die Anzeige nennt ein Portal als Bewerbungsweg. Eine Bewerbung an eine zufällige E-Mail-Adresse folgt dieser Vorgabe nicht. Ort, Schichtbeginn oder konkrete Samstage können noch fehlen. Sammle solche Fragen, bevor du die Stelle als passend bewertest. Speichere Anzeige, Datum und Kennziffer. So kannst du eine spätere Rückmeldung der richtigen Stelle zuordnen.":"اعلان یک پورتال را به عنوان راه درخواست نام می‌برد. یک درخواست به یک آدرس ایمیل تصادفی از این راهنما پیروی نمی‌کند. جا، شروع شیفت یا شنبه‌های مشخص ممکن است هنوز نیامده باشند. چنین سوال‌هایی را جمع کنید، پیش از اینکه کار را مناسب ارزیابی کنید. اعلان، تاریخ و شمارهٔ اعلان (Kennziffer) را ذخیره کنید. به این ترتیب می‌توانید یک جواب بعدی را به کار درست مربوط کنید.","Anzeigenbegriffe ergänzen":"کامل کردن کلمه‌های اعلان","Setze „erwünscht“ und „Portal“ ein.":"„erwünscht“ و „Portal“ را بگذارید.","Beide Angaben stehen im Anzeigentext.":"هر دو معلومات در متن اعلان هستند.","Die Wörter betreffen den gewünschten Hintergrund und den Einreichungsweg.":"این کلمه‌ها به سابقهٔ خواسته‌شده و راه فرستادن مربوط‌اند.","Erfahrung ist ___, nicht ausdrücklich zwingend.":"Erfahrung ist ___, nicht ausdrücklich zwingend. (تجربه ___ است، نه صریحاً اجباری.)","Die Bewerbung erfolgt über das ___.":"Die Bewerbung erfolgt über das ___. (درخواست از راه ___ انجام می‌شود.)","Textstellen einordnen":"مرتب کردن بخش‌های متن","Ordne die Angaben zu.":"معلومات را وصل کنید.","Unterscheide Tätigkeit, Qualifikation und Zeit.":"کار، صلاحیت و وقت را از هم جدا کنید.","Die Anzeige enthält Informationen auf mehreren Ebenen.":"اعلان معلومات را در چند سطح دارد.","Kasse führen":"کار با صندوق","Erfahrung erwünscht":"تجربه مطلوب است","25 Wochenstunden":"25 ساعت در هفته","Den Wochenumfang verstehen":"فهمیدن اندازهٔ کار هفتگی","Wie viele Wochenstunden sind genannt? Antworte als Zahl.":"چند ساعت در هفته نام برده شده؟ به شکل عدد جواب دهید.","Gesucht ist die Stundenzahl, nicht die Zahl der Arbeitstage.":"تعداد ساعت‌ها خواسته شده، نه تعداد روزهای کار.","Die Anzeige nennt 25 Stunden pro Woche.":"اعلان 25 ساعت در هفته را نام می‌برد.","Eine Anzeige auswerten":"ارزیابی یک اعلان","Schreibe vier Sätze: Aufgaben, Stunden, Bedeutung von erwünscht und eine offene Frage.":"چهار جمله بنویسید: کارها، ساعت‌ها، معنای „erwünscht“ و یک سوال باز.","Belege jede Aussage mit einer Stelle im Anzeigentext.":"هر گفته را با جایی از متن اعلان ثابت کنید.","Die Auswertung hält fest, was bekannt und was noch zu klären ist.":"این ارزیابی ثبت می‌کند که چه چیزی معلوم است و چه چیزی هنوز باید روشن شود.","Sind beide Aufgaben enthalten?":"آیا هر دو کار در آن هست؟","Nennst du 25 Wochenstunden und Samstagsarbeit?":"آیا 25 ساعت در هفته و کار شنبه را نام می‌برید؟","Gibst du „erwünscht“ ohne Übertreibung wieder?":"آیا „erwünscht“ را بدون اغراق بیان می‌کنید؟","Fragt dein letzter Satz nach einer tatsächlich offenen Angabe?":"آیا جملهٔ آخر شما دربارهٔ یک معلومات واقعاً باز می‌پرسد؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei arbeitsagentur.de.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در arbeitsagentur.de بررسی کنید.","Bundesagentur für Arbeit: Stellen finden":"ادارهٔ فدرال کار (Bundesagentur für Arbeit): پیدا کردن کار","Anforderungen werden nach ihrem tatsächlichen Wortlaut gelesen.":"شرط‌ها بر اساس کلمه‌های واقعی‌شان خوانده می‌شوند.","Eine Kennziffer erleichtert die spätere Zuordnung der Bewerbung.":"یک شمارهٔ اعلان (Kennziffer) مربوط کردن بعدی درخواست را آسان می‌کند.","Eine Online-Suche sinnvoll eingrenzen":"محدود کردن معقول یک جستجوی آنلاین","Du veränderst Suchbegriffe und Filter gezielt und prüfst passende Treffer genauer.":"شما کلمه‌های جستجو و فلترها را هدفمند تغییر می‌دهید و نتیجه‌های مناسب را دقیق‌تر بررسی می‌کنید.","Suchergebnis mit Zusage verwechseln":"اشتباه گرفتن نتیجهٔ جستجو با قبولی","Falsch: „Ein Treffer bedeutet, dass ich die Stelle bekomme.“ Richtig: Ein Treffer muss geprüft werden und ist noch keine Bewerbung oder Zusage.":"اشتباه: «یک نتیجه یعنی من کار را می‌گیرم.» درست: یک نتیجه باید بررسی شود و هنوز نه درخواست است و نه قبولی.","Alle Filter gleichzeitig verändern":"تغییر هم‌زمان همهٔ فلترها","Falsch: Ort, Umfang und Beruf auf einmal wechseln und daraus eine klare Ursache ableiten. Richtig: Änderungen einzeln testen und vergleichen.":"اشتباه: جا، اندازهٔ کار و شغل را یک‌جا تغییر دهید و از آن یک علت روشن نتیجه بگیرید. درست: تغییرها را یکی‌یکی آزمایش و مقایسه کنید.","Welche erste Änderung passt zu Emils Situation?":"کدام تغییر اول با وضعیت امیل جور می‌آید؟","Den Umkreis von zwei auf zehn Kilometer erweitern.":"بزرگ کردن شعاع از دو به ده کیلومتر.","Nur nach Vollzeit statt nach einer Bürotätigkeit suchen.":"فقط جستجوی تمام‌وقت به جای یک کار دفتری.","Den Radius beibehalten und nur ältere Anzeigen einblenden.":"نگه داشتن شعاع و فقط نشان دادن اعلان‌های قدیمی‌تر.","Emil hat zehn Kilometer als mögliche Grenze genannt; eine gezielte Erweiterung ist nachvollziehbar.":"امیل ده کیلومتر را به عنوان حد ممکن نام برده؛ یک بزرگ کردن هدفمند قابل فهم است.","Was muss bei Büroassistenz erneut geprüft werden?":"در Büroassistenz (دستیار دفتر) چه چیزی را باید دوباره بررسی کرد؟","Nur ob Büroassistenz und Bürohilfe ähnlich klingen.":"فقط اینکه آیا Büroassistenz و Bürohilfe شبیه به نظر می‌رسند.","Nur ob der Arbeitsort innerhalb des neuen Radius liegt.":"فقط اینکه آیا محل کار داخل شعاع تازه است.","Aufgaben und Anforderungen.":"کارها و شرط‌ها.","Ein verwandter Titel beweist keine gleiche Tätigkeit oder gleiche Zugangsvoraussetzung.":"یک عنوان مشابه کار یکسان یا شرط ورود یکسان را ثابت نمی‌کند.","Warum nur einen Filter auf einmal ändern?":"چرا هر بار فقط یک فلتر را تغییر دهیم؟","Damit die erste Trefferzahl unverändert bleibt.":"تا تعداد نتیجه‌های اول تغییر نکند.","Damit die Wirkung der Änderung erkennbar bleibt.":"تا اثر تغییر قابل شناخت بماند.","Damit ein ähnlicher Titel die Prüfung der Aufgaben ersetzt.":"تا یک عنوان مشابه جای بررسی کارها را بگیرد.","Ein einzelner veränderter Faktor ermöglicht einen sinnvollen Vergleich.":"یک عامل تغییرکردهٔ تنها یک مقایسهٔ معقول را ممکن می‌کند.","Ändere bei zu wenigen Treffern jeweils nur einen Filter, damit du die Wirkung erkennen kannst.":"اگر نتیجه‌ها خیلی کم است، هر بار فقط یک فلتر را تغییر دهید تا اثر آن را ببینید.","Eine Suche verbessern":"بهتر کردن یک جستجو","Emil: „Mit Bürohilfe im Umkreis von zwei Kilometern finde ich nichts.“ Sara: „Kannst du weiter fahren?“ Emil: „Bis zehn Kilometer, wenn der Bus passt.“ Sara: „Dann erweitere zuerst nur den Umkreis.“ Emil: „Ich kann außerdem nach Büroassistenz suchen.“ Sara: „Prüfe dann, ob die Aufgaben wirklich zu deinem Profil passen.“":"امیل: «با Bürohilfe در شعاع دو کیلومتر چیزی پیدا نمی‌کنم.» سارا: «می‌توانی دورتر بروی؟» امیل: «تا ده کیلومتر، اگر بس جور باشد.» سارا: «پس اول فقط شعاع را بزرگ کن.» امیل: «می‌توانم علاوه بر آن Büroassistenz را هم جستجو کنم.» سارا: «بعد بررسی کن که آیا کارها واقعاً با پروفایلت جور می‌آیند.»","Suchwort und Filter trennen":"جدا کردن کلمهٔ جستجو و فلتر","Das Suchwort beschreibt zum Beispiel Tätigkeit oder Berufsbezeichnung. Filter grenzen Ort, Umfang oder Veröffentlichungszeit ein. Ein enger Radius kann passende Stellen im Nachbarort ausblenden. Zu viele Änderungen gleichzeitig machen unklar, warum neue Treffer erscheinen. Teste einen weiteren Radius oder einen passenden verwandten Begriff und vergleiche die Ergebnisse.":"کلمهٔ جستجو مثلاً کار یا عنوان شغل را توصیف می‌کند. فلترها جا، اندازهٔ کار یا زمان نشر را محدود می‌کنند. یک شعاع تنگ ممکن است کارهای مناسب در شهرک همسایه را پنهان کند. تغییرهای هم‌زمان زیاد نامعلوم می‌کنند که چرا نتیجه‌های تازه ظاهر می‌شوند. یک شعاع بزرگ‌تر یا یک کلمهٔ مربوط مناسب را آزمایش کنید و نتیجه‌ها را مقایسه کنید.","Treffer nach Inhalt bewerten":"ارزیابی نتیجه‌ها بر اساس محتوا","Ein Treffer ist eine gefundene Stellenanzeige. Er bedeutet noch keine Zusage. Ähnliche Titel können andere Aufgaben meinen: Büroassistenz kann mehr Verantwortung verlangen als Bürohilfe. Lies deshalb auch den Text. Prüfe dann die Busverbindung zum Arbeitsbeginn. Ein naher Ort hilft wenig, wenn morgens kein passender Bus fährt.":"یک نتیجه یک اعلان کار پیدا شده است. هنوز به معنای قبولی نیست. عنوان‌های مشابه ممکن است کارهای دیگری را منظور داشته باشند: Büroassistenz ممکن است از Bürohilfe مسئولیت بیشتری بخواهد. به همین دلیل متن را هم بخوانید. بعد اتصال بس تا شروع کار را بررسی کنید. یک جای نزدیک کمک کمی می‌کند، اگر صبح هیچ بس مناسبی نرود.","Suchstand nachvollziehbar sichern":"ذخیرهٔ قابل پیگیری وضعیت جستجو","Notiere Suchwort, Ort und wichtige Filter für einen späteren Vergleich. Speichere nur passende Anzeigen und die dazugehörigen Originaladressen. Ein Suchauftrag kann neue Treffer melden, doch jede Anzeige muss einzeln geprüft werden. Viele Treffer sind noch kein Erfolg bei der Bewerbung. Prüfe, welche Stellen wirklich zu deiner Erfahrung und deinen Zeiten passen.":"کلمهٔ جستجو، جا و فلترهای مهم را برای یک مقایسهٔ بعدی یادداشت کنید. فقط اعلان‌های مناسب و آدرس‌های اصلی آن‌ها را ذخیره کنید. یک جستجوی ذخیره‌شده ممکن است نتیجه‌های تازه را اعلام کند، اما هر اعلان باید جداگانه بررسی شود. نتیجه‌های زیاد هنوز موفقیت در درخواست نیست. بررسی کنید که کدام کارها واقعاً با تجربه و وقت‌های شما جور می‌آیند.","Suchangaben ergänzen":"کامل کردن معلومات جستجو","Setze „Filter“ und „Treffer“ ein.":"„Filter“ و „Treffer“ (نتیجه) را بگذارید.","Ein Begriff begrenzt die Suche, der andere bezeichnet das Ergebnis.":"یک کلمه جستجو را محدود می‌کند، کلمهٔ دیگر نتیجه را نام می‌برد.","Filter bestimmen, welche Treffer sichtbar werden.":"فلترها تعیین می‌کنند که کدام نتیجه‌ها دیده شوند.","Der Umkreis ist ein ___.":"Der Umkreis ist ein ___. (شعاع یک ___ است.)","Ein Suchergebnis heißt auch ___.":"Ein Suchergebnis heißt auch ___. (یک نتیجهٔ جستجو ___ هم نامیده می‌شود.)","Suchschritte zuordnen":"وصل کردن قدم‌های جستجو","Verbinde die Änderung mit ihrer Funktion.":"تغییر را به کارکرد آن وصل کنید.","Achte darauf, welcher Teil der Suchanfrage verändert wird.":"توجه کنید که کدام بخش درخواست جستجو تغییر می‌کند.","Die Schritte wirken auf unterschiedliche Suchkriterien.":"این قدم‌ها روی معیارهای مختلف جستجو اثر دارند.","Büroassistenz statt Bürohilfe":"Büroassistenz به جای Bürohilfe","zehn statt zwei Kilometer":"ده به جای دو کیلومتر","Teilzeit auswählen":"انتخاب نیمه‌وقت","Den Suchradius hören":"شنیدن شعاع جستجو","Bis zu wie vielen Kilometern möchte Emil suchen? Antworte als Zahl.":"امیل تا چند کیلومتر می‌خواهد جستجو کند؟ به شکل عدد جواب دهید.","Die neue Grenze ersetzt die alte.":"حد تازه جای حد قدیمی را می‌گیرد.","Emil erweitert den Radius auf zehn Kilometer.":"امیل شعاع را به ده کیلومتر بزرگ می‌کند.","Einen Suchversuch dokumentieren":"ثبت یک تلاش جستجو","Schreibe drei Sätze: ursprüngliche Suche, eine Änderung und die anschließende Prüfung.":"سه جمله بنویسید: جستجوی اول، یک تغییر و بررسی بعد از آن.","Beschreibe die Änderung so, dass eine andere Person sie nachvollziehen kann.":"تغییر را طوری توصیف کنید که شخص دیگری بتواند آن را دنبال کند.","Der Versuch hält Ursache, Ergebnisprüfung und praktische Grenze auseinander.":"این تلاش علت، بررسی نتیجه و محدودیت عملی را جدا نگه می‌دارد.","Nennst du Suchwort und ursprünglichen Radius?":"آیا کلمهٔ جستجو و شعاع اول را نام می‌برید؟","Beschreibst du genau eine erste Änderung?":"آیا دقیقاً یک تغییر اول را توصیف می‌کنید؟","Prüfst du die inhaltliche Passung der Treffer?":"آیا جور بودن محتوایی نتیجه‌ها را بررسی می‌کنید؟","Beziehst du die Verbindung zu den Arbeitszeiten ein?":"آیا اتصال وسیلهٔ رفت‌وآمد را با وقت‌های کار در نظر می‌گیرید؟","Ähnliche Stellentitel können unterschiedliche Aufgaben enthalten.":"عنوان‌های مشابه کار ممکن است کارهای مختلفی داشته باشند.","Ein weiter Suchradius muss zum tatsächlichen Arbeitsweg passen.":"یک شعاع جستجوی بزرگ باید با راه واقعی کار جور باشد.","Arbeitgeber und Angebote überprüfen":"بررسی کارفرمایان و پیشنهادها","Du prüfst Absender, Originalanzeige und auffällige Forderungen vor der Weitergabe von Daten.":"شما پیش از دادن داده‌ها فرستنده، اعلان اصلی و درخواست‌های غیرعادی را بررسی می‌کنید.","Logo als Identitätsbeweis behandeln":"لوگو را دلیل هویت دانستن","Falsch: „Mit Firmenlogo ist die Nachricht sicher echt.“ Richtig: Absender und Angebot unabhängig beim Arbeitgeber prüfen.":"اشتباه: «با لوگوی شرکت، پیام حتماً واقعی است.» درست: فرستنده و پیشنهاد را مستقل نزد کارفرما بررسی کنید.","Vorabzahlung als Einstellungsgarantie verstehen":"پیش‌پرداخت را تضمین استخدام دانستن","Falsch: „Wenn ich zahle, habe ich den Arbeitsplatz sicher.“ Richtig: Eine Zahlungsforderung ist keine belastbare Einstellungszusage.":"اشتباه: «اگر پول بدهم، کار را حتماً دارم.» درست: یک درخواست پول قبولی قابل اعتماد استخدام نیست.","Was ist bei der Zahlungsforderung ein sinnvoller nächster Schritt?":"با درخواست پول، قدم بعدی معقول چیست؟","Die Rechnung bezahlen und die Stelle danach prüfen.":"بل را بپردازید و بعد کار را بررسی کنید.","Die Anzeige über einen unabhängigen Firmenkontakt prüfen.":"اعلان را از راه یک تماس مستقل با شرکت بررسی کنید.","Nur die Absenderadresse innerhalb der Nachricht beantworten.":"فقط به آدرس فرستنده داخل پیام جواب دهید.","Ein unabhängig gefundener Kontakt ermöglicht die Prüfung, ohne die Forderung ungeprüft zu erfüllen.":"یک تماس که مستقل پیدا شده بررسی را ممکن می‌کند، بدون اینکه درخواست را بدون بررسی انجام دهید.","Welche Schlussfolgerung ist aus einem Firmenlogo allein zulässig?":"از یک لوگوی شرکت به تنهایی کدام نتیجه مجاز است؟","Die Nachricht wurde nachweislich vom Arbeitgeber versandt.":"پیام به‌طور ثابت‌شده از کارفرما فرستاده شده است.","Die genannte Kontaktperson ist nachweislich zur Bewerbung berechtigt.":"شخص تماس نام‌برده به‌طور ثابت‌شده برای درخواست‌ها مسئول است.","Die Identität des Absenders muss weiterhin unabhängig geprüft werden.":"هویت فرستنده هنوز باید مستقل بررسی شود.","Ein Logo kann kopiert werden und bestätigt den Absender deshalb nicht.":"یک لوگو را می‌شود کاپی کرد و به همین دلیل فرستنده را تأیید نمی‌کند.","Welche Angabe gehört nicht in eine Bewerbung?":"کدام معلومات در یک درخواست کار جا ندارد؟","Ein Bankfreigabecode.":"یک کد تأیید بانکی.","Eine Beschreibung der bisherigen Tätigkeit.":"توضیح کار قبلی.","Eine erreichbare E-Mail-Adresse.":"یک آدرس ایمیل قابل دسترس.","Ein Freigabecode ermöglicht sensible Kontoaktionen und dient nicht der Bewerbung.":"یک کد تأیید کارهای حساس حساب را ممکن می‌کند و برای درخواست کار نیست.","Öffne den Arbeitgeberauftritt über eine selbst geprüfte Adresse und vergleiche dort die Stelle mit der Nachricht.":"صفحهٔ کارفرما را از راه آدرسی که خودتان بررسی کرده‌اید باز کنید و کار را آنجا با پیام مقایسه کنید.","Eine auffällige Nachricht besprechen":"صحبت دربارهٔ یک پیام عجیب","Lea: „Ein angeblicher Arbeitgeber will vor dem Gespräch eine Überweisung für die Ausrüstung.“ Nabil: „Kennst du die Firma und die Stelle?“ Lea: „Nur aus der Nachricht.“ Nabil: „Dann prüfe die Firma unabhängig. Überweise nicht allein wegen dieser Nachricht.“ Lea: „Ich suche die offizielle Kontaktadresse und frage dort nach der Anzeige.“":"لیا: «یک کارفرمای ادعایی پیش از مصاحبه یک واریز پول برای تجهیزات می‌خواهد.» نبیل: «شرکت و کار را می‌شناسی؟» لیا: «فقط از همین پیام.» نبیل: «پس شرکت را مستقل بررسی کن. فقط به خاطر این پیام پول نفرست.» لیا: «آدرس رسمی تماس را جستجو می‌کنم و آنجا دربارهٔ اعلان می‌پرسم.»","Ein einzelnes Signal richtig bewerten":"ارزیابی درست یک نشانهٔ تنها","Ein Firmenlogo beweist weder Echtheit noch die Berechtigung des Absenders. Vergleiche Stellenbezeichnung, Kontaktweg und vollständigen Arbeitgeberauftritt. Zeitdruck und unerwartete Zahlungsforderungen sind Gründe, den Vorgang anzuhalten und genauer zu prüfen. Sie ersetzen jedoch keine Untersuchung der konkreten Nachricht. Ein vertraut klingender Name kann nachgeahmt sein.":"یک لوگوی شرکت نه واقعی بودن را ثابت می‌کند و نه اجازهٔ فرستنده را. عنوان کار، راه تماس و صفحهٔ کامل کارفرما را مقایسه کنید. فشار وقت و درخواست‌های غیرمنتظرهٔ پول دلیل‌هایی هستند که روند را متوقف کنید و دقیق‌تر بررسی کنید. اما جای بررسی پیام مشخص را نمی‌گیرند. یک نام آشنا ممکن است تقلید شده باشد.","Daten sparsam weitergeben":"دادن کم داده‌ها","Ein Lebenslauf enthält persönliche Daten. Prüfe deshalb vor dem Versand, wer sie erhält. Schicke keine Zugangsdaten oder Bankfreigabecodes. Solche Codes gehören nicht zur Bewerbung. Sende auch keine Ausweiskopie an einen ungeprüften Kontakt. Frage bei einem unbekannten Dokumentenwunsch zuerst über einen selbst gefundenen Firmenkontakt nach.":"یک رزومه داده‌های شخصی دارد. به همین دلیل پیش از فرستادن بررسی کنید که چه کسی آن را می‌گیرد. هیچ معلومات ورود یا کد تأیید بانکی نفرستید. چنین کدهایی جزو درخواست کار نیستند. کاپی تذکره را هم به یک تماس بررسی‌نشده نفرستید. اگر سندی ناآشنا خواسته شد، اول از راه یک تماس شرکت که خودتان پیدا کرده‌اید بپرسید.","Eine unabhängige Klärung vorbereiten":"آماده کردن یک روشن‌سازی مستقل","Nutze einen Kontakt, den du selbst über einen geprüften Arbeitgeberauftritt gefunden hast. Antworte nicht nur innerhalb der verdächtigen Nachricht. Frage, ob Stelle und Kontaktperson bekannt sind, ohne zusätzliche sensible Dokumente mitzuschicken. Sichere bei Bedarf die Nachricht für eine Beratung. Eine nicht überprüfbare Forderung ist kein Grund, unter Zeitdruck zu zahlen.":"از تماسی استفاده کنید که خودتان از راه یک صفحهٔ بررسی‌شدهٔ کارفرما پیدا کرده‌اید. فقط داخل پیام مشکوک جواب ندهید. بپرسید که آیا کار و شخص تماس شناخته‌شده‌اند، بدون اینکه اسناد حساس اضافی بفرستید. در صورت نیاز پیام را برای یک مشاوره نگه دارید. یک درخواست غیرقابل بررسی دلیلی برای پرداخت زیر فشار وقت نیست.","Die Prüfung ergänzen":"کامل کردن بررسی","Setze „Absender“ und „Zahlung“ ein.":"„Absender“ (فرستنده) و „Zahlung“ (پرداخت) را بگذارید.","Unterscheide die Person hinter der Nachricht von ihrer Forderung.":"شخص پشت پیام را از درخواست او جدا کنید.","Eine ungeprüfte Forderung wird nicht allein wegen des Firmenlogos erfüllt.":"یک درخواست بررسی‌نشده فقط به خاطر لوگوی شرکت انجام نمی‌شود.","Ich prüfe zuerst den ___.":"Ich prüfe zuerst den ___. (اول ___ را بررسی می‌کنم.)","Die Nachricht verlangt eine unerwartete ___.":"Die Nachricht verlangt eine unerwartete ___. (پیام یک ___ غیرمنتظره می‌خواهد.)","Signale einordnen":"مرتب کردن نشانه‌ها","Der Prüfweg muss außerhalb der fraglichen Nachricht liegen.":"راه بررسی باید بیرون از پیام مورد شک باشد.","Die Zuordnung trennt äußerliche Merkmale, Forderung und Klärung.":"این وصل کردن ویژگی‌های ظاهری، درخواست و روشن‌سازی را جدا می‌کند.","Firmenlogo":"لوگوی شرکت","Vorabüberweisung":"واریز پیش از استخدام","selbst gefundene Firmenadresse":"آدرس شرکت که خودتان پیدا کرده‌اید","Die Forderung erkennen":"شناختن درخواست","Was wird vor dem Gespräch verlangt? Antworte mit einem Nomen.":"پیش از مصاحبه چه چیزی خواسته می‌شود؟ با یک اسم (به آلمانی) جواب دهید.","Gesucht ist die geforderte Handlung.":"کار خواسته‌شده پرسیده شده است.","Die Nachricht verlangt eine Überweisung vor dem Gespräch.":"پیام پیش از مصاحبه یک واریز (Überweisung) می‌خواهد.","Eine Prüfnotiz verfassen":"نوشتن یک یادداشت بررسی","Schreibe vier Sätze zum Fall: Forderung, ungeklärte Echtheit, unabhängiger Kontakt und Entscheidung bis zur Klärung.":"چهار جمله دربارهٔ این مورد بنویسید: درخواست، واقعی بودن نامعلوم، تماس مستقل و تصمیم تا روشن شدن.","Begründe die Prüfung mit dem konkreten Vorgang, nicht nur mit einem Gefühl.":"بررسی را با روند مشخص توجیه کنید، نه فقط با یک احساس.","Die Notiz hält den Befund und die noch nötige Prüfung auseinander.":"این یادداشت یافته و بررسی هنوز لازم را جدا نگه می‌دارد.","Beschreibst du die konkrete Forderung?":"آیا درخواست مشخص را توصیف می‌کنید؟","Bleibt die Echtheit als ungeklärt bezeichnet?":"آیا واقعی بودن نامعلوم توصیف می‌شود؟","Nennst du einen unabhängigen Kontaktweg?":"آیا یک راه تماس مستقل را نام می‌برید؟","Vermeidest du Zahlungs- und Datenfreigabe vor der Klärung?":"آیا پیش از روشن شدن از پرداخت و دادن داده پرهیز می‌کنید؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei verbraucherzentrale.de.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در verbraucherzentrale.de بررسی کنید.","Verbraucherzentrale: gefälschte Stellenanzeigen":"مرکز حمایت از مصرف‌کننده (Verbraucherzentrale): اعلان‌های جعلی کار","Ein bekannter Firmenname kann in einer fremden Nachricht missbraucht werden.":"یک نام شناخته‌شدهٔ شرکت ممکن است در یک پیام بیگانه سوءاستفاده شود.","Empfängerprüfung kommt vor dem Versand persönlicher Bewerbungsdaten.":"بررسی گیرنده پیش از فرستادن داده‌های شخصی درخواست می‌آید.","Kontakte auf einer Jobmesse nutzen":"استفاده از تماس‌ها در یک نمایشگاه کار","Du bereitest ein kurzes Gespräch vor und notierst konkrete nächste Schritte.":"شما یک صحبت کوتاه آماده می‌کنید و قدم‌های بعدی مشخص را یادداشت می‌کنید.","Messegespräch als Einstellung ausgeben":"صحبت در نمایشگاه را استخدام جلوه دادن","Falsch: „Am Stand wurde ich eingestellt“, obwohl nur die Anzeige empfohlen wurde. Richtig: „Ich wurde auf eine passende Ausschreibung hingewiesen.“":"اشتباه: «در غرفه استخدام شدم»، در حالی که فقط اعلان پیشنهاد شده بود. درست: «به یک اعلان مناسب راهنمایی شدم.»","Ohne Suchziel vorstellen":"معرفی بدون هدف جستجو","Falsch: Nur einen Namen nennen und eine sofortige Stelle erwarten. Richtig: Erfahrung, Suchziel und eine konkrete Frage verbinden.":"اشتباه: فقط یک نام بگویید و یک کار فوری انتظار داشته باشید. درست: تجربه، هدف جستجو و یک سوال مشخص را با هم وصل کنید.","Welche Frage passt zu Minas Zeitplanung?":"کدام سوال با برنامهٔ زمانی مینا جور می‌آید؟","Welche Unterlagen brauche ich nach einer Einstellung?":"بعد از استخدام به کدام اسناد نیاز دارم؟","Wie ist die Abteilung am Standort aufgebaut?":"بخش در این شعبه چطور ساخته شده است؟","Welche Schichten sind vorgesehen?":"کدام شیفت‌ها پیش‌بینی شده‌اند؟","Die Schichten bestimmen, ob die Tätigkeit zu ihrer Verfügbarkeit passt.":"شیفت‌ها تعیین می‌کنند که آیا کار با زمان آماده بودن او جور می‌آید.","Was empfiehlt der Referent als nächsten Weg?":"کارمند بخش استخدام کدام راه بعدی را پیشنهاد می‌کند؟","Die Karriereseite des Betriebs prüfen.":"بررسی صفحهٔ کاریابی شرکت.","Direkt am Stand ohne Anzeige einen Vertrag erwarten.":"انتظار یک قرارداد مستقیم در غرفه بدون اعلان.","Die Unterlagen nur an den Namen auf einem fremden Flyer senden.":"فرستادن اسناد فقط به نام روی یک بروشور بیگانه.","Der Referent verweist auf die Originalanzeige auf der Karriereseite.":"کارمند به اعلان اصلی در صفحهٔ کاریابی اشاره می‌کند.","Was ist durch das Gespräch noch nicht erfolgt?":"با این صحبت هنوز چه چیزی انجام نشده است؟","Ein erster Kontakt zum Betrieb.":"یک تماس اول با شرکت.","Eine verbindliche Einstellung.":"یک استخدام الزام‌آور.","Eine Information zum Bewerbungsweg.":"یک معلومات دربارهٔ راه درخواست.","Der Hinweis auf eine Anzeige ist keine Einstellungszusage.":"اشاره به یک اعلان قبولی استخدام نیست.","Bereite eine kurze Vorstellung mit Erfahrung, Suchziel und einer Frage an den Betrieb vor.":"یک معرفی کوتاه با تجربه، هدف جستجو و یک سوال از شرکت آماده کنید.","Am Messestand ins Gespräch kommen":"شروع صحبت در غرفهٔ نمایشگاه","Mina: „Guten Tag, ich habe Erfahrung im Lager und suche eine Teilzeitstelle.“ Personalreferent: „Wir suchen Unterstützung im Wareneingang.“ Mina: „Welche Schichten sind vorgesehen?“ Referent: „Früh- und Spätschicht im Wechsel. Die Anzeige steht auf unserer Karriereseite.“ Mina: „Dann prüfe ich die Zeiten und bewerbe mich dort mit der Kennziffer.“":"مینا: «روز بخیر، در گدام تجربه دارم و یک کار نیمه‌وقت جستجو می‌کنم.» کارمند استخدام: «ما برای بخش دریافت جنس کمک لازم داریم.» مینا: «کدام شیفت‌ها پیش‌بینی شده‌اند؟» کارمند: «شیفت صبح و عصر به نوبت. اعلان در صفحهٔ کاریابی ما است.» مینا: «پس وقت‌ها را بررسی می‌کنم و آنجا با شمارهٔ اعلان درخواست می‌دهم.»","Eine kurze Vorstellung strukturieren":"ساختار دادن به یک معرفی کوتاه","Nenne zuerst einen relevanten Hintergrund und danach dein Suchziel. Eine lange Lebensgeschichte erschwert den Einstieg. Eine konkrete Frage zeigt, was du klären möchtest. „Welche Schichten sind vorgesehen?“ passt zu Minas Zeitplanung. „Sie stellen mich doch sofort ein?“ setzt dagegen eine Entscheidung voraus, die bei einem ersten Kontakt noch nicht gefallen ist.":"اول یک سابقهٔ مربوط و بعد هدف جستجوی خود را بگویید. یک داستان طولانی زندگی شروع را سخت می‌کند. یک سوال مشخص نشان می‌دهد که چه چیزی را می‌خواهید روشن کنید. „Welche Schichten sind vorgesehen?“ با برنامهٔ زمانی مینا جور می‌آید. اما „Sie stellen mich doch sofort ein?“ (شما مرا فوراً استخدام می‌کنید، درست؟) تصمیمی را پیش‌فرض می‌گیرد که در یک تماس اول هنوز گرفته نشده است.","Gespräch und Bewerbungsweg verbinden":"وصل کردن صحبت و راه درخواست","Notiere nach dem Gespräch Betrieb, Datum und die genannte Stelle. Eine Kennziffer ist die Nummer der Anzeige. Sie hilft, die richtige Stelle wiederzufinden. Frage nach dem Bewerbungsweg. Möchtest du den Namen der Kontaktperson nennen? Frage, ob du dich in der Bewerbung auf das Gespräch beziehen darfst.":"بعد از صحبت، شرکت، تاریخ و کار نام‌برده را یادداشت کنید. یک Kennziffer شمارهٔ اعلان است. کمک می‌کند کار درست را دوباره پیدا کنید. دربارهٔ راه درخواست بپرسید. می‌خواهید نام شخص تماس را بگویید؟ بپرسید که آیا اجازه دارید در درخواست به این صحبت اشاره کنید.","Nach der Messe gezielt handeln":"کار هدفمند بعد از نمایشگاه","Prüfe die erwähnte Originalanzeige und vergleiche Schichten, Ort und Anforderungen mit deinem Profil. Halte Datum, Betrieb und nächsten Schritt fest. Schreibe nicht, die Person habe eine Einstellung zugesagt, wenn sie nur auf das Portal verwiesen hat. Ein Bezug wie „Vielen Dank für das Gespräch auf der Jobmesse“ kann passen, sofern das Gespräch wirklich stattgefunden hat.":"اعلان اصلی نام‌برده را بررسی کنید و شیفت‌ها، جا و شرط‌ها را با پروفایل خود مقایسه کنید. تاریخ، شرکت و قدم بعدی را ثبت کنید. ننویسید که آن شخص استخدام را قبول کرده، اگر فقط به پورتال اشاره کرده است. یک اشاره مثل „Vielen Dank für das Gespräch auf der Jobmesse“ (از صحبت در نمایشگاه کار سپاسگزارم) ممکن است مناسب باشد، به شرط اینکه صحبت واقعاً انجام شده باشد.","Die Vorstellung ergänzen":"کامل کردن معرفی","Setze „Lager“ und „Teilzeitstelle“ ein.":"„Lager“ (گدام) و „Teilzeitstelle“ (کار نیمه‌وقت) را بگذارید.","Die Angaben stehen direkt in Minas Einstieg.":"این معلومات مستقیم در شروع صحبت مینا هستند.","Die Vorstellung verbindet bisherigen Bereich und gewünschte Beschäftigung.":"این معرفی بخش قبلی و استخدام دلخواه را به هم وصل می‌کند.","Mina hat Erfahrung im ___.":"Mina hat Erfahrung im ___. (مینا در ___ تجربه دارد.)","Sie sucht eine ___.":"Sie sucht eine ___. (او یک ___ جستجو می‌کند.)","Gesprächselemente zuordnen":"وصل کردن بخش‌های صحبت","Verbinde die Aussage mit ihrer Funktion.":"گفته را به کارکرد آن وصل کنید.","Eine kurze Vorstellung enthält verschiedene Informationen.":"یک معرفی کوتاه معلومات مختلفی دارد.","Der Aufbau führt vom Profil zum konkreten Informationsbedarf.":"این ساختار از پروفایل به نیاز مشخص معلومات می‌برد.","Ich habe Lagererfahrung.":"من تجربهٔ گدام دارم.","Ich suche Teilzeit.":"من کار نیمه‌وقت جستجو می‌کنم.","Welche Schichten gibt es?":"کدام شیفت‌ها وجود دارند؟","Den Bereich der Stelle verstehen":"فهمیدن بخش کار","In welchem Bereich wird Unterstützung gesucht?":"در کدام بخش کمک جستجو می‌شود؟","Unterscheide den besetzten Bereich vom gesuchten.":"بخش پرشده را از بخش جستجوشده جدا کنید.","Die offene Tätigkeit betrifft den Wareneingang.":"کار باز به بخش دریافت جنس (Wareneingang) مربوط است.","Ein Messegespräch nachbereiten":"پیگیری یک صحبت در نمایشگاه","Schreibe drei Sätze zu Kontakt, Schichtinformation und nächstem Schritt.":"سه جمله دربارهٔ تماس، معلومات شیفت و قدم بعدی بنویسید.","Halte Informationen fest, die dir bei der späteren Auswahl helfen.":"معلوماتی را ثبت کنید که در انتخاب بعدی به شما کمک می‌کنند.","Die Notiz macht aus dem Kontakt einen konkreten Prüfschritt.":"این یادداشت از تماس یک قدم بررسی مشخص می‌سازد.","Ist der besprochene Bereich richtig genannt?":"آیا بخش صحبت‌شده درست نام برده شده است؟","Sind Früh- und Spätschicht enthalten?":"آیا شیفت صبح و عصر در آن هست؟","Bezeichnest du die Karriereseite als nächsten Prüfweg?":"آیا صفحهٔ کاریابی را به عنوان راه بررسی بعدی نام می‌برید؟","Verzichtest du auf eine erfundene Einstellungszusage?":"آیا از یک قبولی ساختگی استخدام پرهیز می‌کنید؟","Ein Messekontakt kann den Bewerbungsweg klären, ersetzt ihn aber nicht.":"یک تماس در نمایشگاه می‌تواند راه درخواست را روشن کند، اما جای آن را نمی‌گیرد.","Die Nachbereitung hält nur tatsächlich besprochene Angaben fest.":"پیگیری فقط معلوماتی را ثبت می‌کند که واقعاً گفته شده است.","Stellen mit einer einfachen Matrix vergleichen":"مقایسهٔ کارها با یک جدول ساده","Du vergleichst Angebote nach denselben Kriterien und markierst fehlende Angaben.":"شما پیشنهادها را با معیارهای یکسان مقایسه می‌کنید و معلومات کم را علامت می‌زنید.","Fehlende Angabe positiv erfinden":"ساختن مثبت یک معلومات کم","Falsch: Unbekannte Schichten als sichere Vormittage eintragen. Richtig: „Schichtzeiten offen“ notieren und nachfragen.":"اشتباه: شیفت‌های نامعلوم را به عنوان صبح‌های مطمئن بنویسید. درست: „Schichtzeiten offen“ (وقت شیفت باز) را یادداشت کنید و بپرسید.","Punkte über feste Grenzen stellen":"گذاشتن امتیاز بالاتر از محدودیت‌های ثابت","Falsch: Ein kurzer Weg gleicht jede unpassende Arbeitszeit aus. Richtig: Nicht erfüllbare Muss-Kriterien gesondert behandeln.":"اشتباه: یک راه کوتاه هر وقت کار نامناسب را جبران می‌کند. درست: معیارهای اجباری غیرقابل انجام را جدا در نظر بگیرید.","Welche Information fehlt bei A?":"کدام معلومات در A کم است؟","Die Nähe zum Arbeitsort.":"نزدیکی به محل کار.","Die Schichtzeiten.":"وقت‌های شیفت.","Die festen Vormittage von B.":"صبح‌های ثابت B.","A ist als nah beschrieben, aber die konkrete Verteilung der Arbeit ist unbekannt.":"A نزدیک توصیف شده، اما تقسیم مشخص کار نامعلوم است.","Welcher Vergleich ist sachlich?":"کدام مقایسه واقع‌بینانه است؟","A passt zeitlich, weil der Arbeitsort nahe liegt.":"A از نظر زمانی جور می‌آید، چون محل کار نزدیک است.","B passt bereits vollständig, weil feste Vormittage genannt sind.":"B از همین حالا کاملاً جور است، چون صبح‌های ثابت نام برده شده‌اند.","B hat feste Vormittage; der Arbeitsweg muss noch geprüft werden.":"B صبح‌های ثابت دارد؛ راه کار هنوز باید بررسی شود.","Die Aussage trennt einen bekannten Vorteil von einem noch offenen Punkt.":"این گفته یک مزیت معلوم را از یک نکتهٔ هنوز باز جدا می‌کند.","Was sollte Noah zuerst bei A klären?":"نوح در A اول چه چیزی را باید روشن کند؟","Ob die Zeiten mit seiner Verfügbarkeit vereinbar sind.":"اینکه آیا وقت‌ها با زمان آماده بودن او جور می‌آیند.","Ob der kurze Weg die Arbeitszeiten entbehrlich macht.":"اینکه آیا راه کوتاه وقت‌های کار را غیرضروری می‌کند.","Ob der Firmenname derselbe wie in der Übersicht ist.":"اینکه آیا نام شرکت همان نام در خلاصه است.","Die Arbeitszeit ist wegen seiner Betreuung eine entscheidende Voraussetzung.":"وقت کار به خاطر نگهداری از کودک یک شرط تعیین‌کننده است.","Benutze für beide Stellen dieselben Kriterien, damit du keine Äpfel mit Birnen vergleichst.":"برای هر دو کار معیارهای یکسان به کار ببرید تا چیزهای ناجور را با هم مقایسه نکنید.","Zwischen zwei Stellen abwägen":"سنجیدن بین دو کار","Noah: „A ist nah, aber die Schichten fehlen. B ist weiter weg und hat feste Vormittage.“ Lara: „Was ist dir besonders wichtig?“ Noah: „Vormittage sind wegen meiner Betreuung nötig.“ Lara: „Dann klärst du bei A zuerst die Zeiten. Nähe allein reicht nicht.“ Noah: „B bleibt möglich, wenn der Arbeitsweg rechtzeitig machbar ist.“":"نوح: «A نزدیک است، اما شیفت‌ها معلوم نیست. B دورتر است و صبح‌های ثابت دارد.» لارا: «چه چیزی برایت به‌خصوص مهم است؟» نوح: «صبح‌ها به خاطر نگهداری از کودک لازم است.» لارا: «پس در A اول وقت‌ها را روشن کن. نزدیکی به تنهایی کافی نیست.» نوح: «B ممکن می‌ماند، اگر راه کار به موقع شدنی باشد.»","Kriterien gleich anwenden":"به کار بردن یکسان معیارها","Lege Spalten für Tätigkeiten, Zeiten, Ort, Anforderungen und offene Fragen an. Trage nur belegte Informationen ein. Fehlt eine Angabe, schreibe „offen“. Frage nach, bevor du die Stelle bewertest. Prüfe feste Grenzen zuerst. Sind die Schichten unklar, kannst du die Zeiten noch nicht beurteilen. Frage beim Betrieb nach.":"ستون‌هایی برای کارها، وقت‌ها، جا، شرط‌ها و سوال‌های باز بسازید. فقط معلومات ثابت‌شده را بنویسید. اگر معلوماتی نیست، «باز» بنویسید. پیش از ارزیابی کار بپرسید. اول محدودیت‌های ثابت را بررسی کنید. اگر شیفت‌ها نامشخص‌اند، هنوز نمی‌توانید وقت‌ها را ارزیابی کنید. از محل کار بپرسید.","Gewichtungen nachvollziehbar halten":"قابل پیگیری نگه داشتن وزن‌ها","Ein Kriterium ist ein Punkt, nach dem du Angebote vergleichst. Für Noah sind feste Vormittage besonders wichtig. Ein kurzer Weg kann eine unpassende Arbeitszeit nicht ausgleichen. Schreibe daher zu jeder Bewertung einen Grund. Punkte allein reichen nicht: Prüfe zuerst, ob die Stelle deine festen Zeitgrenzen einhält.":"یک معیار نکته‌ای است که بر اساس آن پیشنهادها را مقایسه می‌کنید. برای نوح صبح‌های ثابت به‌خصوص مهم است. یک راه کوتاه نمی‌تواند یک وقت کار نامناسب را جبران کند. به همین دلیل برای هر ارزیابی یک دلیل بنویسید. امتیاز به تنهایی کافی نیست: اول بررسی کنید که آیا کار محدودیت‌های زمانی ثابت شما را رعایت می‌کند.","Eine vorläufige Auswahl treffen":"انجام یک انتخاب موقت","Ordne die Stellen nach deinen wichtigsten Kriterien. Begründe die Reihenfolge und nenne offene Fragen. „B passt derzeit besser, weil die Vormittage feststehen; den Arbeitsweg muss ich noch testen“ ist präziser als „B ist perfekt“. Stelle anschließend eine konkrete Frage zu A. Nach der Antwort aktualisierst du den Vergleich. So bleibt die Entscheidung mit neuen Informationen überprüfbar.":"کارها را بر اساس مهم‌ترین معیارهای خود مرتب کنید. ترتیب را توجیه کنید و سوال‌های باز را نام ببرید. «B فعلاً بهتر جور است، چون صبح‌ها ثابت‌اند؛ راه کار را هنوز باید آزمایش کنم» دقیق‌تر از «B عالی است» است. بعد یک سوال مشخص دربارهٔ A بپرسید. بعد از جواب، مقایسه را به‌روز می‌کنید. به این ترتیب تصمیم با معلومات تازه قابل بررسی می‌ماند.","Einen Vergleich ergänzen":"کامل کردن یک مقایسه","Setze „offen“ und „Vormittage“ ein.":"„offen“ (باز) و „Vormittage“ (صبح‌ها) را بگذارید.","Unbekanntes bleibt unbekannt, bekannte Zeiten werden übernommen.":"نامعلوم نامعلوم می‌ماند، وقت‌های معلوم نوشته می‌شوند.","Die Einträge unterscheiden Informationslücke und bestätigte Angabe.":"این نوشته‌ها کمبود معلومات و معلومات تأییدشده را جدا می‌کنند.","Die Schichten bei A sind noch ___.":"Die Schichten bei A sind noch ___. (شیفت‌های A هنوز ___ است.)","B nennt feste ___.":"B nennt feste ___. (B ___ ثابت را نام می‌برد.)","Kriterien zuordnen":"وصل کردن معیارها","Ordne das Beispiel dem Kriterium zu.":"مثال را به معیار وصل کنید.","Wende dieselben Felder auf beide Angebote an.":"خانه‌های یکسان را برای هر دو پیشنهاد به کار ببرید.","Nur gleichartige Kriterien lassen sich sinnvoll gegenüberstellen.":"فقط معیارهای هم‌نوع را می‌شود معقول در برابر هم گذاشت.","feste Vormittage":"صبح‌های ثابت","zwanzig Minuten Busfahrt":"بیست دقیقه سفر با بس","Kasse bedienen":"کار با صندوق","Das feste Zeitfenster hören":"شنیدن بازهٔ زمانی ثابت","Welche Tageszeit ist für Noah nötig? Antworte im Singular.":"کدام وقت روز برای نوح لازم است؟ به شکل مفرد (به آلمانی) جواب دهید.","Gesucht ist das verfügbare Arbeitszeitfenster.":"بازهٔ زمانی در دسترس کار خواسته شده است.","Noah kann die Arbeit am Vormittag mit seiner Betreuung verbinden.":"نوح می‌تواند کار در صبح را با نگهداری از کودک جمع کند.","Eine vorläufige Auswahl begründen":"توجیه یک انتخاب موقت","Schreibe vier Sätze zu A und B, der wichtigen Grenze und dem nächsten Prüfschritt.":"چهار جمله دربارهٔ A و B، محدودیت مهم و قدم بررسی بعدی بنویسید.","Vermeide eine endgültige Zusage, solange die entscheidenden Angaben fehlen.":"تا وقتی معلومات تعیین‌کننده نیست، از یک قبولی نهایی پرهیز کنید.","Die Auswahl führt zu konkreten Klärungen statt einer unbegründeten Rangliste.":"این انتخاب به جای یک رتبه‌بندی بی‌دلیل به روشن‌سازی‌های مشخص می‌انجامد.","Vergleichst du bekannte Angaben statt Vermutungen?":"آیا معلومات معلوم را مقایسه می‌کنید، نه حدس‌ها را؟","Bleibt die Lücke bei A sichtbar?":"آیا کمبود در A دیده می‌ماند؟","Begründest du die Bedeutung der Vormittage?":"آیا اهمیت صبح‌ها را توجیه می‌کنید؟","Nennst du einen Prüfschritt für beide Angebote?":"آیا برای هر دو پیشنهاد یک قدم بررسی نام می‌برید؟","„Offen“ ist ein gültiger Eintrag, solange eine Information fehlt.":"«باز» تا وقتی معلوماتی کم است یک نوشتهٔ معتبر است.","Eine begründete Auswahl bleibt bei neuen Angaben veränderbar.":"یک انتخاب توجیه‌شده با معلومات تازه قابل تغییر می‌ماند.","Die Jobsuche mit kleinen Schritten organisieren":"منظم کردن جستجوی کار با قدم‌های کوچک","Du planst Suchzeiten, dokumentierst Rückmeldungen und leitest passende Folgeaufgaben ab.":"شما وقت‌های جستجو را برنامه‌ریزی می‌کنید، جواب‌ها را ثبت می‌کنید و کارهای بعدی مناسب را از آن بیرون می‌کشید.","Ein nicht beeinflussbares Tagesziel setzen":"تعیین یک هدف روزانهٔ غیرقابل اثرگذاری","Falsch: „Heute muss ich eingestellt werden.“ Richtig: „Heute prüfe ich zwei passende Anzeigen und notiere offene Fragen.“":"اشتباه: «امروز باید استخدام شوم.» درست: «امروز دو اعلان مناسب را بررسی می‌کنم و سوال‌های باز را یادداشت می‌کنم.»","Eingangsbestätigung als Zusage markieren":"علامت زدن تأیید دریافت به عنوان قبولی","Falsch: Den Status nach einer automatischen Antwort auf „eingestellt“ setzen. Richtig: Den tatsächlichen Eingang bestätigen und weitere Entscheidungen abwarten.":"اشتباه: بعد از یک جواب خودکار وضعیت را «استخدام‌شده» بگذارید. درست: دریافت واقعی را تأیید کنید و منتظر تصمیم‌های بعدی بمانید.","Welches Tagesziel ist direkt beeinflussbar?":"کدام هدف روزانه مستقیم قابل اثرگذاری است؟","Heute auf jeden Fall eine Einladung erhalten.":"امروز حتماً یک دعوت بگیرم.","Zwei Anzeigen anhand des Profils prüfen.":"دو اعلان را بر اساس پروفایل بررسی کنم.","Bis heute Abend die Antwort des Betriebs bekommen.":"تا امشب جواب شرکت را بگیرم.","Das Prüfen kann Aylin selbst durchführen; fremde Entscheidungen kann sie nicht erzwingen.":"بررسی را آیلین خودش می‌تواند انجام دهد؛ تصمیم دیگران را نمی‌تواند اجبار کند.","Was bedeutet eine automatische Eingangsbestätigung?":"یک تأیید دریافت خودکار یعنی چه؟","Die Unterlagen sind eingegangen.":"اسناد رسیده‌اند.","Die Bewerbung wurde für ein Gespräch ausgewählt.":"درخواست برای مصاحبه انتخاب شده است.","Die Unterlagen sind inhaltlich vollständig geprüft.":"اسناد از نظر محتوا کامل بررسی شده‌اند.","Der Eingang ist bestätigt, eine inhaltliche Entscheidung damit noch nicht.":"دریافت تأیید شده، اما یک تصمیم محتوایی با آن هنوز نه.","Welche Angabe erleichtert die Zuordnung ähnlicher Stellen?":"کدام معلومات مربوط کردن کارهای مشابه را آسان می‌کند؟","Die allgemeine Bezeichnung des Arbeitgebers.":"عنوان عمومی کارفرما.","Die Kennziffer der Anzeige.":"شمارهٔ اعلان (Kennziffer).","Der Ort, an dem die Anzeige gefunden wurde.":"جایی که اعلان پیدا شد.","Die Kennziffer identifiziert die konkrete Ausschreibung.":"شمارهٔ اعلان اعلان مشخص را شناسایی می‌کند.","Plane pro Suchtermin ein erreichbares Ergebnis, zum Beispiel zwei geprüfte Anzeigen statt „endlich Arbeit finden“.":"برای هر وقت جستجو یک نتیجهٔ قابل رسیدن برنامه‌ریزی کنید، مثلاً دو اعلان بررسی‌شده به جای «بالاخره کار پیدا کنم».","Einen Wochenplan besprechen":"صحبت دربارهٔ یک برنامهٔ هفتگی","Aylin: „Ich suche jeden Abend, verliere aber den Überblick.“ Berater: „Was hältst du fest?“ Aylin: „Nur die Firmennamen.“ Berater: „Ergänze Stelle, Kennziffer, Datum und nächsten Schritt.“ Aylin: „Montag prüfe ich zwei Anzeigen. Dienstag kläre ich offene Zeiten. Danach bereite ich die passende Bewerbung vor.“":"آیلین: «هر شب جستجو می‌کنم، اما رشتهٔ کار از دستم می‌رود.» مشاور: «چه چیزی را ثبت می‌کنی؟» آیلین: «فقط نام شرکت‌ها را.» مشاور: «کار، شمارهٔ اعلان، تاریخ و قدم بعدی را اضافه کن.» آیلین: «دوشنبه دو اعلان را بررسی می‌کنم. سه‌شنبه وقت‌های باز را روشن می‌کنم. بعد از آن درخواست مناسب را آماده می‌کنم.»","Einen überschaubaren Suchrhythmus entwickeln":"ساختن یک ریتم جستجوی قابل مدیریت","Eine kurze feste Suchzeit kann hilfreicher sein als stundenlanges ungeordnetes Klicken. Trenne Recherche, Rückfrage und Bewerbungsvorbereitung. Das Ziel einer Sitzung sollte beeinflussbar sein: „zwei Anzeigen auswerten“ liegt in deiner Hand, „heute eingestellt werden“ nicht. Plane Pausen und eine spätere Prüfung neuer Antworten ein.":"یک وقت جستجوی کوتاه و ثابت ممکن است از ساعت‌ها کلیک کردن نامنظم مفیدتر باشد. جستجو، پرسیدن و آماده کردن درخواست را جدا کنید. هدف هر نشست باید قابل اثرگذاری باشد: «دو اعلان را ارزیابی کنم» در دست شماست، «امروز استخدام شوم» نه. برای استراحت‌ها و یک بررسی بعدی جواب‌های تازه برنامه بگذارید.","Status ohne falsche Fortschrittsangaben notieren":"ثبت وضعیت بدون پیشرفت ساختگی","Halte für jede Stelle den tatsächlichen Stand fest. „Gefunden“ heißt: Du hast eine Anzeige entdeckt. „Geprüft“ heißt: Du hast sie mit deinem Profil verglichen. „Versandt“ schreibst du erst nach dem Absenden. Eine automatische Antwort bestätigt meist nur den Eingang. Warte auf eine eigene Einladung oder Entscheidung.":"برای هر کار وضعیت واقعی را ثبت کنید. „Gefunden“ (پیدا شد) یعنی: یک اعلان را کشف کرده‌اید. „Geprüft“ (بررسی شد) یعنی: آن را با پروفایل خود مقایسه کرده‌اید. „Versandt“ (فرستاده شد) را فقط بعد از فرستادن بنویسید. یک جواب خودکار معمولاً فقط دریافت را تأیید می‌کند. منتظر یک دعوت یا تصمیم جداگانه بمانید.","Zur Bewerbungsvorbereitung übergehen":"رفتن به سوی آماده کردن درخواست","Wähle nach der Prüfung eine passende Stelle aus und sammle ihre Anforderungen. Im anschließenden Bewerbungskurs entwickelst du Lebenslauf, Anschreiben und Unterlagen daraus. Bewahre alte Notizen so auf, dass du Entscheidungen nachvollziehen kannst, und entferne unnötige persönliche Daten aus Übungsdateien. Eine wöchentliche Rückschau zeigt, welcher Suchbegriff oder Filter brauchbare Ergebnisse geliefert hat.":"بعد از بررسی یک کار مناسب را انتخاب کنید و شرط‌های آن را جمع کنید. در کورس بعدی درخواست کار، رزومه، نامهٔ درخواست و اسناد را از آن می‌سازید. یادداشت‌های قدیمی را طوری نگه دارید که بتوانید تصمیم‌ها را دنبال کنید و داده‌های شخصی غیرضروری را از فایل‌های تمرینی بردارید. یک مرور هفتگی نشان می‌دهد که کدام کلمهٔ جستجو یا فلتر نتیجه‌های مفید داده است.","Suchstatus vervollständigen":"کامل کردن وضعیت جستجو","Setze „geprüft“ und „versandt“ ein.":"„geprüft“ و „versandt“ را بگذارید.","Benutze Statuswörter erst nach der zugehörigen Handlung.":"کلمه‌های وضعیت را فقط بعد از کار مربوط به کار ببرید.","Der Status dokumentiert das abgeschlossene Ereignis.":"وضعیت رویداد تمام‌شده را ثبت می‌کند.","Die Anzeige ist gelesen und mit dem Profil verglichen: ___.":"Die Anzeige ist gelesen und mit dem Profil verglichen: ___. (اعلان خوانده و با پروفایل مقایسه شده: ___.)","Die Bewerbung wurde tatsächlich abgeschickt: ___.":"Die Bewerbung wurde tatsächlich abgeschickt: ___. (درخواست واقعاً فرستاده شد: ___.)","Suchschritte strukturieren":"ساختار دادن به قدم‌های جستجو","Verbinde den Schritt mit seinem Ergebnis.":"قدم را به نتیجهٔ آن وصل کنید.","Unterscheide Recherche von Versand und Entscheidung.":"جستجو را از فرستادن و تصمیم جدا کنید.","Jeder kleine Schritt erzeugt ein überprüfbares Zwischenergebnis.":"هر قدم کوچک یک نتیجهٔ میانی قابل بررسی می‌سازد.","Anzeige auswerten":"ارزیابی اعلان","Zeiten nachfragen":"پرسیدن وقت‌ها","Unterlagen vorbereiten":"آماده کردن اسناد","Das Wochenziel verstehen":"فهمیدن هدف هفتگی","Wie viele Anzeigen will Aylin am Montag prüfen? Schreibe eine Zahl.":"آیلین می‌خواهد دوشنبه چند اعلان را بررسی کند؟ یک عدد بنویسید.","Gesucht ist die Zahl der geprüften Anzeigen am Montag.":"تعداد اعلان‌های بررسی‌شده در دوشنبه خواسته شده است.","Aylin plant zunächst zwei gründliche Prüfungen.":"آیلین اول دو بررسی دقیق را برنامه‌ریزی می‌کند.","Einen realistischen Suchplan schreiben":"نوشتن یک برنامهٔ جستجوی واقع‌بینانه","Schreibe vier Sätze mit Suchtermin, prüfbarem Ergebnis, Rückfrage und Dokumentation.":"چهار جمله با وقت جستجو، نتیجهٔ قابل بررسی، سوال و ثبت بنویسید.","Plane erst die Prüfung und dann die passende Bewerbung.":"اول بررسی و بعد درخواست مناسب را برنامه‌ریزی کنید.","Der Plan führt von überschaubarer Recherche zu einem gezielten nächsten Schritt.":"این برنامه از جستجوی قابل مدیریت به یک قدم بعدی هدفمند می‌رسد.","Ist ein konkreter Suchtermin genannt?":"آیا یک وقت جستجوی مشخص نام برده شده است؟","Beschreibst du ein selbst beeinflussbares Ergebnis?":"آیا یک نتیجه را توصیف می‌کنید که خودتان بر آن اثر دارید؟","Enthält der Plan eine gezielte Rückfrage?":"آیا برنامه یک سوال هدفمند دارد؟","Dokumentierst du Status und Kennziffer nachvollziehbar?":"آیا وضعیت و شمارهٔ اعلان را قابل پیگیری ثبت می‌کنید؟","Ein Tagesziel beschreibt eine Handlung, die du selbst ausführen kannst.":"یک هدف روزانه کاری را توصیف می‌کند که خودتان می‌توانید انجام دهید.","Der Suchstatus wird nach tatsächlichen Ereignissen aktualisiert.":"وضعیت جستجو بعد از رویدادهای واقعی به‌روز می‌شود."};})(typeof window!=="undefined"?window:globalThis);
